import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MoonLoader from "react-spinners/MoonLoader";

import "./Upload.css";

function Upload() {
  const [videoFile, setVideoFile] = useState(null);
  const [transcript, setTranscript] = useState(""); // Real-time transcript hopefully
  const [feedback, setFeedback] = useState("");
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState({});
  const [status, setStatus] = useState("");
  const navigate = useNavigate();

  // Update the file state when the user selects a file
  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
  };

  // This works when the user clicks "Analyze File"
  const handleAnalyze = async () => {
    console.log("start");
    setStatus("processing");

    const formData = new FormData();
    formData.append("video", videoFile);
    try {
      if (videoFile.current) {
        videoFile.current.play();
      }
      const response = await fetch("http://34.55.142.231:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        // Handles error response from the backend
        const errorData = await response.json().catch(() => ({}));
        const errMsg = errorData.error || "Error processing video. Please try again.";
        setTranscript(errMsg);
        return;
      }

      // Show what the backend returns
      const data = await response.json();
      console.log("Analysis Data:", data);

      setTranscript(data.transcript);
      setFeedback(data.ai_feedback);
      setAnalysis(data);
    } catch (error) {
      console.error("Error analyzing video:", error);
      setFeedback("Error processing video. Please try again.");
    }
  };
  console.log(status);

  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {/* Video Upload & Transcript Side by Side */}
      {videoFile && status === "processing" ? (
        <div className="dashboard-content">
          {/* Left Side: Video Upload */}
          <div className="video-section">
            <div className="video-player">
              <div className="dashboard-header">
                <h2 className="video-title">{videoFile.name}</h2>
              </div>
              <video controls>
                <source play src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            </div>

            {/* Right Side: Real-time Transcript */}
            <div className="transcript-box">
              <div className="transcript-box-content">
                <h2 className="transcript-box-title">Transcript</h2>
                {transcript ? (
                  <textarea
                    value={transcript}
                    readOnly
                    style={{
                      height: "320px",
                      fontSize: "16px",
                      margin: "0px",
                      padding: "10px",
                      border: "none",
                      resize: "none",
                      backgroundColor: "transparent",
                      overflowY: "auto",
                    }}
                  />
                ) : (<div className="loader-div">
                  <MoonLoader size={50} aria-label="Loading Spinner" data-testid="loader" />
                </div>)}
              </div>
              {videoFile ? (
                <div className="save-button-div">
                  <button className="save-button">Save & Upload New Video</button>
                </div>
              ) : (
                <div className="save-button-div">
                  <button className="save-button-disabled" disabled title="Please upload a video file to begin">
                    Save & Upload New Video
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* AI Feedback Box */}
          <div className="feedback-box">
            {feedback ? (
              <div>
                <h2>Speech Analysis</h2>
                <p><strong>Speech Rate:</strong> {analysis.speech_rate_wps} words/sec</p>
                <p><strong>Number of Pauses:</strong> {analysis.num_pauses}</p>
                <p><strong>Total Silence:</strong> {analysis.total_silence_sec} sec</p>
                <p><strong>Average Pitch:</strong> {analysis.average_pitch} Hz</p>
                <h2>AI Feedback</h2>
                <p>{feedback}</p>
              </div>
            ) : (<div className="loader-div">
              <MoonLoader size={50} aria-label="Loading Spinner" data-testid="loader" />
            </div>)}
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {videoFile ? (
              <video controls>
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            ) : (
              <input type="file" accept="video/*" onChange={handleFileChange} />
            )}
            <button onClick={handleAnalyze}>Analyze Video</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default Upload;
